pub fn build_extract_output(
    task: impl Into<String>,
    task_id: impl Into<String>,
    timestamp: impl Into<String>,
    steps: &[StepRecord],
) -> Option<ExtractOutput> {
    let task = task.into();
    let task_id = task_id.into();
    let timestamp = timestamp.into();
    let extracts: Vec<ExtractRecord> = steps
        .iter()
        .enumerate()
        .filter_map(|(index, step)| {
            if !step.result.ok {
                return None;
            }
            let extract = step.result.extract.as_ref()?;
            if !matches!(step.action, Action::Extract { .. }) {
                return None;
            }
            Some(ExtractRecord {
                step_index: index + 1,
                query: extract.query.clone(),
                id: extract.id.clone(),
                value: extract.value.clone(),
            })
        })
        .collect();

    if extracts.is_empty() {
        None
    } else {
        Some(ExtractOutput {
            schema_version: EXTRACT_OUTPUT_SCHEMA_VERSION,
            run_id: run_id_for(&task_id, &timestamp),
            task_id,
            task,
            timestamp,
            extracts,
        })
    }
}

pub fn write_extract_output(path: &Path, output: &ExtractOutput) -> io::Result<()> {
    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() {
            std::fs::create_dir_all(parent)?;
        }
    }
    let data = serde_json::to_vec(output)
        .map_err(|err| io::Error::new(io::ErrorKind::Other, err))?;
    let mut file = std::fs::OpenOptions::new()
        .create(true)
        .read(true)
        .append(true)
        .open(path)?;
    let len = file.metadata()?.len();
    if len > 0 {
        file.seek(SeekFrom::End(-1))?;
        let mut buf = [0u8; 1];
        file.read_exact(&mut buf)?;
        if buf[0] != b'\n' {
            file.write_all(b"\n")?;
        }
    }
    file.write_all(&data)?;
    file.write_all(b"\n")?;
    Ok(())
}

